Here's a Web Component using Shadow DOM that mimics the `<details>` element behavior with the requested functionality:

```html
<!DOCTYPE html>
<html>
<head>
  <style>
  </head>
  <body>
    <x-details style="padding: 16px; background: yellow; border: 1px solid black; border-radius: 8px; display: flex; flex-direction: column; max-width: 200px;">
      <span slot="header">Button to expand</span>
      <div slot="intro">This intro part is always visible.</div>
      <div slot="details">This details part will be hidden by default.</div>
      <div slot="close">X</div>
    </x-details>
  </body>
</html>
```

```javascript
// <x-details> implementation
let xDetailsInstance = null;

class Details extends HTMLicer {
  constructor() {
    super();
    this.expanded = false;
    this.opener = null;
  }

  setupRoot() {
    this.root = this.createRoot();
  }

  createRoot() {
    const wrapper = document.createElement('div');
    wrapper.setAttribute('slot', 'label');
    wrapper.className = 'details-wrapper details-open';

    const toggleButton = document.createElement('button');
    toggleButton.setAttribute('slot', 'toggle');
    toggleButton.innerHTML = this.expanded ? '−' : '+';

    const header = document.createElement('span');
    header.setAttribute('slot', 'header');
    header.style.fontSize = '1.25em';
    header.style.marginBottom = '0';

    const headerContainer = document.createElement('div');
    headerContainer.appendChild(header);

    const intro = document.createElement('div');
    intro.setAttribute('slot', 'intro');

    const details = document.createElement('div');
    details.setAttribute('slot', 'details');

    const closeButton = document.createElement('div');
    closeButton.setAttribute('slot', 'close');
    closeButton.innerHTML = '×';
    closeButton.style.marginLeft = '8px';

    wrapper.appendChild(toggleButton);
    wrapper.appendChild(headerContainer);
    wrapper.appendChild(intro);
    wrapper.appendChild(details);
    wrapper.appendChild(closeButton);

    return wrapper;
  }

  getRoot() {
    return this.root;
  }

  connectedCallback() {
    const wrapper = this.getRoot();

    // Add styles to the container
    wrapper.style.minHeight = '80px';
    wrapper.style.marginBottom = '8px';

    // Update the toggle button when expanded state changes
    const toggleButton = wrapper.querySelector('[slot="toggle"]');
    toggleButton.addEventListener('click', this.toggle);

    // Add a close button that closes the component when clicked
    const closeButton = wrapper.querySelector('[slot="close"]');
    closeButton.addEventListener('click', this.close);
  }

  disconnectedCallback() {
    this.removeFromDOM();
  }

  handleAnimationRequest(webkitAnimationEndRequest) {
  }

  // Called when the element is added to the DOM
  connectedToDOMNode(node) {
    const root = node.closest(this.ID);

    // Initialize the instance if not already done
    if (!xDetailsInstance) {
      xDetailsInstance = new Details(root);
    } else {
      const current = xDetailsInstance.getRoot();
      if (current === node) {
        // Already initialized
      } else {
        xDetailsInstance.removeFromDOM();
        xDetailsInstance = new Details(root);
      }
    }
  }

  // Function to check if the parent container has the .details list
  isOpener(node) {
    return node.closest('details-list') !== null;
  }

  // Toggle between collapsed and expanded states
  toggle() {
    if (!this.opener) return;

    // If expanding
    if (!this.expanded) {
      if (this.opener) {
        this.opener.close();
      }
      this.expanded = true;
      this.root.className = 'details-wrapper details-open';
      this.root.focus();
    }
    // If collapsing
    else {
      this.root.className = 'details-wrapper details-collapsed';
      if (this.opener) {
        this.opener.open();
      }
      this.expanded = false;
    }
  }

  close() {
    // Close without triggering onClose, because the root itself contains other elements
    this.opener = null;
  }

  removeFromDOM() {
    xDetailsInstance = null;
  }
}

// Create a CSS animation for the collapsing effect
const animation = {
  name: "closeAnimation",
  steps: [
    { type: "setting", duration: 150, setting: { opacity: 1 } },
    { type: "wait", wait: 0 },
    { type: "setting", duration: 150, setting: { opacity: 0 } },
    { type: "wait", wait: 50 },
    { type: "setting", duration: 30, setting: { opacity: 0 } }
  ]
};

// Add effect to the x-details element
Details.prototype.applyEffect = function(node) {
  node.closest('details-wrapper').className += ' details-with-effect';
  node.closest('details-wrapper').classList.add('style-marker-details-with-effect');
  node.closest('details-wrapper').classList.remove('style-marker-details');
};

// This is called when the element is connected to the HTML Element
Details.prototype.isConnectedToDOMNode = () => {};
