        for (int i = 0; i < S; ++i) {
            mallDist[i].resize(N);
            mallDist[i][stores[i]] = 0;
            mallDist[i] = stores[i]; // copy pointer to do dijkstra correctly
            dijkstra(stores[i], mallDist[i], g);
        }

        // ------------------------------------------------------------------
        // 3️⃣ Reduce to an explicit distance matrix for the TSP graph
        // The TSP graph vertices will be:
        //    0 (house)
        //    1 .. S (store 0 .. S-1)
        // ------------------------------------------------------------------
        // matrix[row][col] = distance between vertex `row` and `col`
        // We'll make a matrix of length S+1.
        vector<vector<lint>> TSPMat(S+1, vector<lint>(S+1, INF));
        // 0 → i (house → store i)
        for (int i = 0; i < S; ++i)
            TSPMat[0][1+i] = hDist[stores[i]];
        for (int i = 1; i <= S; ++i)
            TSPMat[i][0] = hDist[i]; // symmetry (undirected)

//        for pairs of distinct stores:
        for (int i = 0; i < S; ++i)
            for (int j = 0; j < S; ++j)
                TSPMat[i+1][j+2] = mallDist[i][stores[j]]; // store i → store j

        // (symmetry: TSPMat is undirected, you can leave the lower left blank)

        // ------------------------------------------------------------------
        // 4️⃣ Traveling Salesman DP (Held‑Karp).
        // Include house as vertex 0, stores as 1..S.
        // ------------------------------------------------------------------
        int V = S+1;                 // number of vertices in TSP
        int allMask = (1<<S) - 1;   // all stores visited

        // dp[mask][i] = minimum length to leave from house,
        //               visit exactly the stores encoded by mask,
        //               and currently be at store i (i∈[1,S] → 0-indexed store index)
        // Use an array to lighten memory, mask size = 2^S.

        // We treat store i as index i-1 in dp.
        long long dp[1<<S];           // only S entries per mask, store west one endpoint at a time.
        // To keep clarity we keep dp[mask][i] in a 2‑D vector shape:
        vector< vector<long long> > dp(S+1, vector<long long>(S+1, INF));

        // Initialize: start for each store, we have visited only that store.
        for (int i = 1; i <= S; ++i)
            dp[1<<(i-1)][i] = TSPMat[0][i];

        // Transitions
        for (int mask = 0; mask < (1<<S); ++mask) {
            for (int i = 1; i <= S; ++i)          // current endpoint store vertex
                if (dp[mask][i]) {
                    for (int j = 1; j <= S; ++j) { // next store vertex j (1‑based)
                        if (!(mask & (1<<(j-1)))) { // not visited yet
                            int newMask = mask | (1<<(j-1));
                            dp[newMask][j] = min(dp[newMask][j],
                                                dp[mask][i] + TSPMat[i][j]);
                        }
                    }
                }
            }
        }

        // Return to house
        long long best = INF;
        for (int i = 1; i <= S; ++i)
            best = min(best, dp[allMask][i] + TSPMat[i][0]);

        cout << best << '\n';
    }
    return 0;
}
```

