## My answer to the prompt

For direct microphone capture, use `FAudioCapture` from the **AudioCaptureCore** module. This is separate from `UAudioCaptureComponent`. The exact callback API can vary slightly between UE versions, but a typical setup is:

```cpp
// MyGameMode.h
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "AudioCapture.h"
#include "MyGameMode.generated.h"

UCLASS()
class YOURGAME_API AMyGameMode : public AGameModeBase
{
    GENERATED_BODY()

public:
    virtual void BeginPlay() override;
    virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

private:
    FAudioCapture Capture;
    bool bStreamOpen = false;
};
```

```cpp
// MyGameMode.cpp
#include "MyGameMode.h"

void AMyGameMode::BeginPlay()
{
    Super::BeginPlay();

    FAudioCaptureDeviceInfo DeviceInfo;
    if (!Capture.GetDefaultCaptureDeviceInfo(DeviceInfo))
    {
        UE_LOG(LogTemp, Warning, TEXT("No default audio input device is available."));
        return;
    }

    FAudioCaptureDeviceParams Params;
    Params.DeviceIndex = DeviceInfo.DeviceIndex;
    Params.NumInputChannels = DeviceInfo.InputChannels;
    Params.SampleRate = DeviceInfo.PreferredSampleRate;

    const bool bOpened = Capture.OpenAudioCaptureStream(
        Params,
        FOnAudioCaptureFunction::CreateLambda(
            [](const float* AudioData, int32 NumFrames, int32 NumChannels,
               int32 SampleRate, double StreamTime, bool bOverflow)
            {
                // Called on the audio-capture thread. Copy/enqueue data here
                // if the game thread needs to process it; avoid UObject work here.
            }),
        1024);

    if (!bOpened)
    {
        UE_LOG(LogTemp, Error, TEXT("Could not open the audio capture stream."));
        return;
    }

    bStreamOpen = true;
    if (!Capture.StartStream())
    {
        UE_LOG(LogTemp, Error, TEXT("Could not start the audio capture stream."));
        Capture.CloseStream();
        bStreamOpen = false;
    }
}

void AMyGameMode::EndPlay(const EEndPlayReason::Type EndPlayReason)
{
    if (bStreamOpen)
    {
        Capture.StopStream();
        Capture.CloseStream();
        bStreamOpen = false;
    }

    Super::EndPlay(EndPlayReason);
}
```

Enable the Audio Capture plugin and add `AudioCaptureCore` to the module dependencies in your `.Build.cs`. Also, `GameMode` exists only on the server in networked games, not on clients; for capturing a player’s microphone in a multiplayer game, put this logic in a client-side class or subsystem instead.

